arguments.command:
cd /workspace && python3 -c "
import sys,json,traceback; sys.path.insert(0,'/workspace/dev')
import importlib.util
spec=importlib.util.spec_from_file_location('mp','/workspace/submission/main.py')
mp=importlib.util.module_from_spec(spec); spec.loader.exec_module(mp)
data=open('/workspace/dev/fail.json').read()
orig=mp.need
def need(ok):
    if not ok:
        traceback.print_stack()
        raise mp.Invalid('invalid')
    return orig(ok)
mp.need=need
req=json.loads(data, object_pairs_hook=mp.pairs, parse_constant=mp.invalid_constant, parse_float=mp.finite)
try:
    mp.transport(req)
except Exception as e:
    print('EXC',e)
" 2>&1 | tail -25
